      "interpretation": "Fechamento acima das MMs 20/50/200 — viés altista em todos os prazos."
    },
    {
      "indicator": "MM20",
      "reading": "16.0720",
      "interpretation": "Suporte dinâmico de curto prazo (BB_mid); preço está ~R$0,72 acima; MM20 ascendente."
    },
    {
      "indicator": "MM50",
      "reading": "14.9162",
      "interpretation": "Suporte de médio prazo; distância até o preço atual indica força relativa do movimento."
    },
    {
      "indicator": "MM200",
      "reading": "13.1540",
      "interpretation": "Tendência de longo prazo claramente altista; suporte estrutural relevante."
    },
    {
      "indicator": "EMA9",
      "reading": "16.5151",
      "interpretation": "EMA9 acima da EMA21 e preço acima da EMA9 — impulso de curtíssimo prazo favorável aos compradores."
    },
    {
      "indicator": "EMA21",
      "reading": "16.0593",
      "interpretation": "Referência de curtíssimo prazo; serve como suporte alternativo imediato."
    },
    {
      "indicator": "MACD",
      "reading": "MACD 0.5203 / signal 0.5214 / hist -0.0011",
      "interpretation": "MACD positivo (viés comprador no médio prazo) mas histograma ligeiramente negativo indica enfraquecimento momentâneo do impulso."
    },
    {
      "indicator": "RSI14",
      "reading": "71.0977",
      "interpretation": "Acima de 70 — condição de sobrecompra; maior probabilidade de correção ou consolidação no curto prazo."
    },
    {
      "indicator": "Bandas de Bollinger",
      "reading": "BB_lower 14.9319 / BB_mid 16.0720 / BB_upper 17.2121 (posição do preço ≈81% da faixa)",
      "interpretation": "Preço próximo da banda superior; bandas ampliadas indicam volatilidade aumentada e risco de esticadas/exaustão."
    },
    {
      "indicator": "Volume",
      "reading": "21,139,945,600",
      "interpretation": "Volume elevado que confirma o movimento de alta; similar ao pregão de 2025-09-30 (≈21,48 bi)."
    }
  ]
